<?php use App\Core\View;ob_start(); ?><h1>Administração da plataforma</h1><div class="grid"><article><b>R$ <?=number_format(($data['totals']['revenue']??0)/100,2,',','.')?></b><br>Receita quitada</article><article><b><?=$data['totals']['paid_count']??0?></b><br>Pagamentos quitados</article><article><b><?=$data['totals']['overdue_count']??0?></b><br>Inadimplências</article></div><h2>Assinantes por plano</h2><table><tr><th>Plano</th><th>Assinantes</th><th>Ativos</th></tr><?php foreach($data['plans'] as $p):?><tr><td><?=View::e($p['name'])?></td><td><?=$p['subscribers']?></td><td><?=$p['active']?></td></tr><?php endforeach?></table><h2>Usuários</h2><table><tr><th>Nome</th><th>E-mail</th><th>Plano</th><th>Assinatura</th><th>Acesso</th></tr><?php foreach($data['users'] as $u):?><tr><td><?=View::e($u['full_name'])?></td><td><?=View::e($u['email'])?></td><td><?=View::e($u['plan']??'-')?></td><td><?=View::e($u['subscription_status']??'-')?></td><td><?=$u['access_blocked_at']?'Bloqueado':'Liberado'?></td></tr><?php endforeach?></table><h2>Inadimplentes</h2><table><tr><th>Usuário</th><th>E-mail</th><th>Em aberto</th><th>Controle</th></tr><?php foreach($data['overdue'] as $u):?><tr><td><?=View::e($u['full_name'])?></td><td><?=View::e($u['email'])?></td><td>R$ <?=number_format($u['amount_cents']/100,2,',','.')?></td><td><form method="post" action="/admin/bloquear"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><input name="reason" value="Inadimplência"><button>Bloquear</button></form><form method="post" action="/admin/desbloquear"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button>Desbloquear</button></form></td></tr><?php endforeach?></table><?php $body=ob_get_clean();$title='Administração';require __DIR__.'/layout.php'; ?>
